CREATE TABLE WORDS
    (
        W_ID INTEGER PRIMARY KEY  AUTOINCREMENT  NOT NULL,
        W_WORD VARCHAR(250) NOT NULL,
        CONSTRAINT WORDS_IX1 UNIQUE (W_WORD)
    );

CREATE TABLE RELATED_GROUP_WORDS
    (
        RGW_ID INTEGER PRIMARY KEY  AUTOINCREMENT  NOT NULL,
        RG_ID INTEGER NOT NULL,
        RGW_WORD VARCHAR(250) NOT NULL,
        RGW_NOTE VARCHAR(250),
        RGW_ORDER INTEGER NOT NULL,
        CONSTRAINT RELATED_GROUP_WORDS_FK1 FOREIGN KEY (RG_ID) REFERENCES RELATED_GROUPS (RG_ID) ON
    DELETE
        RESTRICT
    );

CREATE TABLE "RELATED_GROUPS" ("RG_ID" INTEGER PRIMARY KEY  NOT NULL ,"W_ID" INTEGER NOT NULL ,"RG_PART_OF_SPEECH" VARCHAR(250) NOT NULL  DEFAULT (null) ,"RG_ORDER" INTEGER NOT NULL );

